(function(root){
const images=["data:image/png;base64,","data:image/png;base64,"];
function enabled(d){return d?.stickers===true;}
function photos(d){return enabled(d)?images.map((data,i)=>({id:'hanpyeon-sticker-'+i,name:'sticker-'+i+'.png',mime:'png',data})):[];}
function sections(d){if(!enabled(d))return d.sections;return [{heading:'✦',body:'',photoIds:['hanpyeon-sticker-0']},...d.sections,{heading:'♡',body:'',photoIds:['hanpyeon-sticker-1']}];}
const api={images,enabled,photos,sections};if(typeof module!=='undefined')module.exports=api;else root.HanpyeonDecorations=api;
})(typeof window!=='undefined'?window:globalThis);